#!/usr/bin/env python3
import gzip, base64
from pathlib import Path
from datetime import datetime, timezone
stamp = datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%SZ')
js = gzip.decompress(base64.b64decode(''))
css = gzip.decompress(base64.b64decode(''))
jp = Path('/opt/liquidgov/assets/juketube.js')
cp = Path('/opt/liquidgov/assets/juketube.css')
jp.with_name(jp.name + '.bak-v10-' + stamp).write_bytes(jp.read_bytes())
if cp.exists():
    cp.with_name(cp.name + '.bak-v10-' + stamp).write_bytes(cp.read_bytes())
jp.write_bytes(js)
cp.write_bytes(css)
print('js', len(js), 'css', len(css))
srcp = Path('/opt/liquidgov/src/http_server.cpp')
s = srcp.read_text()
need = 0
OLD = '} else if (s.find("\\"ended\\"") != std::string::npos) {'
NEW = '} else if (auto rawp = extract_json_string_field(s, "\\"play\\"")) {\n                    if (auto id = extract_youtube_id(trim_ws(*rawp))) {\n                        std::lock_guard<std::mutex> lock(g_community_mu);\n                        auto& now_playing = g_community_now_by_station[station];\n                        auto& upcoming = g_community_upcoming_by_station[station];\n                        std::deque<CommunityTrack> kept;\n                        for (const auto& t : upcoming) {\n                            if (t.video_id != *id) kept.push_back(t);\n                        }\n                        upcoming.swap(kept);\n                        const auto ts = std::chrono::duration_cast<std::chrono::seconds>(\n                            std::chrono::system_clock::now().time_since_epoch()).count();\n                        now_playing = CommunityNowPlaying{*id, username, ts, true};\n                    }\n                } else if (s.find("\\"ended\\"") != std::string::npos) {'
n = s.count(OLD)
print('ended_hits', n)
marker = 'extract_json_string_field(s, "\\"play\\"")'
if marker in s:
    print('play_already_present')
elif n == 1:
    s = s.replace(OLD, NEW, 1)
    srcp.with_name(srcp.name + ".bak-v10-" + stamp).write_text(srcp.read_text())
    srcp.write_text(s)
    need = 1
    print('cpp_play_patched')
else:
    print('STOP ended_hits', n)
print('NEED_BUILD', need)
print('DONE')
